SCRIPT=r'''
<script>(()=>{const toggle=document.getElementById('menu-toggle'),sidebar=document.getElementById('sidebar'),workspace=document.getElementById('workspace'),overlay=document.getElementById('nav-overlay'),close=document.getElementById('sidebar-close'),mobile=matchMedia('(max-width:860px)');let previous=null;function setOpen(open){if(!mobile.matches)open=false;document.body.classList.toggle('nav-open',open);toggle.setAttribute('aria-expanded',String(open));if(mobile.matches)sidebar.setAttribute('aria-hidden',String(!open));else sidebar.removeAttribute('aria-hidden');if(open)previous=document.activeElement;workspace.inert=open;sidebar.inert=mobile.matches&&!open;if(open){close.focus()}else if(previous){previous.focus();previous=null}}toggle.addEventListener('click',()=>setOpen(true));close.addEventListener('click',()=>setOpen(false));overlay.addEventListener('click',()=>setOpen(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')setOpen(false)});sidebar.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setOpen(false)));sidebar.addEventListener('keydown',e=>{if(e.key!=='Tab'||!document.body.classList.contains('nav-open'))return;const all=[...sidebar.querySelectorAll('button,a')].filter(n=>n.getClientRects().length),first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}});mobile.addEventListener('change',()=>setOpen(false));setOpen(false)})();
</script>
'''

def page_shell(title,content,connection,state):
    active=ACTIVE.get(title);page_title,subtitle=PAGES.get(active,(title,'DMECOM 錄音管理台'))
    def nav(path,label,name):return '<a class="nav-link" href="'+path+'"'+(' aria-current="page"' if active==path else '')+'>'+icon(name)+'<span>'+label+'</span></a>'
    label={'online':'答錄機已連線','unavailable':'答錄機暫時離線','unknown':'等待連線確認'}.get(state.get('status'),'等待連線確認')
    sidebar='<aside id="sidebar" class="sidebar" aria-label="功能欄"><button type="button" id="sidebar-close" class="sidebar-close" aria-label="關閉功能選單">'+icon('close')+'</button><a class="brand" href="/"><span class="brand-mark">'+icon('wave')+'</span><span class="brand-title">DMECOM<span class="brand-subtitle">錄音管理台</span></span></a><nav class="sidebar-nav" aria-label="主要功能"><div class="nav-group"><div class="nav-group-title">錄音工作區</div>'+nav('/','錄音與備份','wave')+'</div><div class="nav-group"><div class="nav-group-title">管理</div>'+nav('/voices','招呼語','audio')+nav('/announcement','接聽宣告','notice')+nav('/settings','設備設定','settings')+'</div></nav><div class="sidebar-footer"><div class="sidebar-device">'+icon('server')+'DAR-A4100LS</div><div class="sidebar-meta">NAS 本地備份 · Tailscale 存取</div><div id="sidebar-connection" class="sidebar-status" data-state="'+esc(state.get('status','unknown'))+'"><span class="status-dot"></span><span id="sidebar-connection-label">'+esc(label)+'</span></div><div class="line-note"><b>正式使用</b>　線路 1<br><b>功能測試</b>　線路 2–4</div></div></aside>'
    header='<header class="topbar"><button type="button" class="menu-toggle" id="menu-toggle" aria-label="開啟功能選單" aria-controls="sidebar" aria-expanded="false">'+icon('menu')+'</button><div class="page-heading"><div class="page-eyebrow">DMECOM / 錄音管理</div><h1>'+esc(page_title)+'</h1><p class="page-subtitle">'+esc(subtitle)+'</p></div><span class="local-badge">'+icon('server')+'NAS 本地管理</span></header>'
    return '<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' · DMECOM</title><style>'+CSS+'</style></head><body><a class="skip-link" href="#main-content">跳到主要內容</a>'+sidebar+'<button type="button" id="nav-overlay" class="nav-overlay" aria-label="關閉功能選單" tabindex="-1"></button><div class="workspace" id="workspace">'+header+'<main id="main-content" class="workspace-main" tabindex="-1">'+connection+content+'</main></div>'+SCRIPT+'</body></html>'
